#if SWITCH
			private static extern bool Ngs_LoginAsync(uint asyncId, uint gameServerId, ref global::NexPlugin.Detail.CppArray accessKey, ulong nsaId, ref global::NexPlugin.Detail.CppArray nsaIdToken, int timeOut);
#else
			private static bool Ngs_LoginAsync(uint asyncId, uint gameServerId, ref global::NexPlugin.Detail.CppArray accessKey, ulong nsaId, ref global::NexPlugin.Detail.CppArray nsaIdToken, int timeOut) { return PcPlatform.PcNex.ServiceCall("Ngs_LoginAsync"); }
#endif
			// @024cec90: the token goes out in a zeroed 0xc01-byte buffer (at most 0xc00 bytes copied)
			public static bool LoginAsync(out uint asyncId, uint gameServerId, string accessKey, global::nn.account.NetworkServiceAccountId nsaId, byte[] nsaIdToken, int timeOut = 30000, global::NexPlugin.NgsFacade.LoginCB callback = null) {
                List<IntPtr> useptr = new List<IntPtr>();
                CppArray accessKeyArray = CppArray.StringToArray(useptr, accessKey);
                byte[] token = new byte[0xc01];
                Array.Clear(token, 0, token.Length);
                int length = nsaIdToken.Length;
                if (length > 0xbff)
                    length = 0xc00;
                Array.Copy(nsaIdToken, token, length);
                CppArray tokenArray = CppArray.ArrayToArray(useptr, token);
                asyncId = PublishAsyncId();
                bool ret = Ngs_LoginAsync(asyncId, gameServerId, ref accessKeyArray, nsaId.id, ref tokenArray, timeOut);
                if (callback != null && ret)
                    AddNexResultCallback(asyncId, callback);
                foreach (IntPtr p in useptr)
                    Util_UnmanagedManager.FreeHGlobal(p, false);
                return ret;
            }
