			// @024cf170: pParam1 -> principal id, pParam2 = the NgsFacade
			private static void NGSLoginResult(ref global::NexPlugin.Detail.AsyncResultInt asyncResult, object callback) {
                NexPlugin.NgsFacade.LoginCB cb = callback as NexPlugin.NgsFacade.LoginCB;
                if (cb != null)
                    cb(AsyncResultInt.GetAsyncResult(asyncResult), asyncResult.GetUlong(asyncResult.pParam1), asyncResult.pParam2);
            }
			// @024cf680
			private static void TestConnectivityResult(ref global::NexPlugin.Detail.AsyncResultInt asyncResult, object callback) {
				NexPlugin.NgsFacade.TestConnectivityCB cb = callback as NexPlugin.NgsFacade.TestConnectivityCB;
				if (cb != null)
					cb(AsyncResultInt.GetAsyncResult(asyncResult), asyncResult.netErrCode == 0);
			}
			// @024cfbb0 (both result helpers inlined)
			public static void Callback(global::NexPlugin.Detail.AsyncResultInt res, object callback) {
				switch (res.asyncNum)
				{
					case AsyncResultNum.COMMON_NGSLOGIN:
						NGSLoginResult(ref res, callback);
						break;
					case AsyncResultNum.COMMON_NGSLOGOUT:
						GetAsyncResult(ref res, callback);
						break;
					case AsyncResultNum.COMMON_TESTCONNECTIVITY:
						TestConnectivityResult(ref res, callback);
						break;
				}
			}
		}
